Tack coat","Trade term \u2014 Tack coat: A light first spray coat for adhesion."], ["Mil thickness","Trade term \u2014 Mil thickness: Paint film thickness; a key quality metric."], ["Sheen","Trade term \u2014 Sheen: Gloss level: flat, eggshell, satin, semi-gloss, gloss."], ["Primer","Trade term \u2014 Primer: The bonding undercoat."], ["Caulk","Trade term \u2014 Caulk: Flexible filler for gaps before painting."], ["Spackle","Trade term \u2014 Spackle: Quick-drying filler for small holes."], ["TSP substitute","Trade term \u2014 TSP substitute: Cleaner for prepping greasy surfaces."], ["Airless sprayer","Trade term \u2014 Airless sprayer: High-pressure paint spraying equipment."], ["Tip size","Trade term \u2014 Tip size: Sprayer tip determining fan width and flow."], ["Overspray","Trade term \u2014 Overspray: Unwanted spray mist on nearby surfaces."], ["Drop cloth","Trade term \u2014 Drop cloth: Floor and furniture protection."], ["Painter's tape","Trade term \u2014 Painter's tape: Low-tack masking tape for crisp lines."], ["Wet edge","Trade term \u2014 Wet edge: Keeping the working edge wet to avoid lap marks."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
